function hitungBelanja(namaBarang, hargaStr, jumlahStr, diskonPersen) {
    let harga = Number(hargaStr);
    let jumlah = Number(jumlahStr);
    let subtotal = harga * jumlah;
    let total = Math.round(subtotal - (subtotal * diskonPersen / 100));
    return namaBarang + ': Rp' + total + ' (diskon ' + diskonPersen + '%)';
}

