    let harga;
    if (umur < 12) harga = 25000;
    else if (umur <= 17) harga = 35000;
    else if (umur <= 59) harga = 50000;
    else harga = 30000;
    if (hari === 'sabtu' || hari === 'minggu') harga += 5000;
    if (isMember) harga = Math.round(harga * 0.85);
    return 'Tiket: Rp' + harga;
}

