let siswa = [];
function render() {
  let tbody = document.getElementById('tbody');
  tbody.innerHTML = '';
  let total = 0;
  siswa.forEach(function(s) {
    total += s.nilai;
    let tr = document.createElement('tr');
    tr.innerHTML = '<td>' + s.nama + '</td><td>' + s.nilai + '</td>';
    tbody.appendChild(tr);
  });
  document.getElementById('rata').textContent = siswa.length
    ? 'Rata-rata: ' + (total / siswa.length).toFixed(1)
    : 'Rata-rata: -';
}
document.getElementById('btnTambah').addEventListener('click', function() {
  let nama = document.getElementById('nama').value.trim();
  let nilai = Number(document.getElementById('nilai').value);
  if (!nama || isNaN(nilai)) return;
  siswa.push({ nama: nama, nilai: nilai });
  document.getElementById('nama').value = '';
  document.getElementById('nilai').value = '';
  render();
});

